// ── Tree helper: find nearest ancestor container that has a loop set ──────────
function findLoopAncestor(
  root: ComponentNode,
  targetId: string,
): ContainerNode | null {
  if ('children' in root && Array.isArray((root as ContainerNode).children)) {
    const container = root as ContainerNode;
    for (const child of container.children ?? []) {
      if (child.id === targetId) {
        return container.loop?.trim() ? container : null;
      }
      const found = findLoopAncestor(child, targetId);
      if (found) return found;
    }
  }
  if ('child' in root && (root as SizedBoxNode).child) {
    const sb = root as SizedBoxNode;
    if (sb.child!.id === targetId) return null;
    return findLoopAncestor(sb.child!, targetId);
  }
  return null;
}

